import{_ as n,o as t,c as i,a3 as a}from"./chunks/framework.B5WAEDB7.js";const s="/screenshots/de/erste-schritte/schnellstart/schritt-1-space-anlegen.png",r="/screenshots/de/erste-schritte/schnellstart/schritt-2-spaltentyp-waehlen.png",l="/screenshots/de/erste-schritte/schnellstart/schritt-2-grid-mit-feldern.png",b=JSON.parse('{"title":"In 15 Minuten zur ersten Anwendung","description":"Ein durchgehendes Beispiel — von der leeren Tabelle bis zur automatischen Bestätigung.","frontmatter":{"title":"In 15 Minuten zur ersten Anwendung","description":"Ein durchgehendes Beispiel — von der leeren Tabelle bis zur automatischen Bestätigung."},"headers":[],"relativePath":"erste-schritte/schnellstart.md","filePath":"erste-schritte/schnellstart.md","lastUpdated":1786260457000}'),d={name:"erste-schritte/schnellstart.md"};function o(c,e,u,h,g,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="in-15-minuten-zur-ersten-anwendung" tabindex="-1">In 15 Minuten zur ersten Anwendung <a class="header-anchor" href="#in-15-minuten-zur-ersten-anwendung" aria-label="Permalink to &quot;In 15 Minuten zur ersten Anwendung&quot;">​</a></h1><p>Diese Anleitung baut eine vollständige, kleine Anwendung: eine <strong>Veranstaltungsanmeldung</strong>. Am Ende können sich Menschen über einen Link anmelden, erhalten automatisch eine Bestätigung, und Sie sehen den Stand auf einen Blick.</p><p>Sie durchlaufen dabei alle vier Bausteine von ApptiveGrid — Grid, Formular, Flow und Seite.</p><hr><h2 id="_1-·-space-und-grid-anlegen-2-minuten" tabindex="-1">1 · Space und Grid anlegen (2 Minuten) <a class="header-anchor" href="#_1-·-space-und-grid-anlegen-2-minuten" aria-label="Permalink to &quot;1 · Space und Grid anlegen (2 Minuten)&quot;">​</a></h2><ol><li>Klicken Sie in der Übersicht auf <strong>Neuen Space erstellen</strong> und nennen Sie ihn <code>Veranstaltungen</code>.</li><li>Legen Sie danach das erste Grid an: <code>Anmeldungen</code>.</li></ol><p><img src="'+s+'" alt="Der Dialog zum Anlegen eines Space, die Schaltfläche Erstellen ist hervorgehoben"></p><p>→ <a href="/spaces/space-anlegen">Space anlegen</a></p><h2 id="_2-·-felder-anlegen-3-minuten" tabindex="-1">2 · Felder anlegen (3 Minuten) <a class="header-anchor" href="#_2-·-felder-anlegen-3-minuten" aria-label="Permalink to &quot;2 · Felder anlegen (3 Minuten)&quot;">​</a></h2><p>Legen Sie über das <strong>+</strong> am rechten Ende der Spaltenköpfe diese Felder an:</p><table tabindex="0"><thead><tr><th>Spaltenname</th><th>Spaltentyp</th></tr></thead><tbody><tr><td><code>Name</code></td><td>Text</td></tr><tr><td><code>E-Mail</code></td><td>E-Mail</td></tr><tr><td><code>Personen</code></td><td>Zahl</td></tr><tr><td><code>Status</code></td><td>Einzelauswahl mit den Optionen <code>Neu</code>, <code>Bestätigt</code>, <code>Abgesagt</code></td></tr></tbody></table><p>Den Typ wählen Sie beim Anlegen der Spalte aus:</p><p><img src="'+r+'" alt="Die Auswahl des Spaltentyps beim Anlegen eines Feldes"></p><p>Danach steht das Grid mit seinen Feldern:</p><p><img src="'+l+`" alt="Das Grid Anmeldungen mit den Feldern Name, E-Mail und Personen"></p><div class="tip custom-block"><p class="custom-block-title">Der Typ ist die wichtigste Entscheidung</p><p>Ein E-Mail-Feld prüft die Eingabe, ein Zahlenfeld lässt sich summieren, eine Einzelauswahl wird später zu den Spalten eines Kanban-Boards. Text kann all das nicht.</p><p>→ <a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></p></div><h2 id="_3-·-formular-erstellen-3-minuten" tabindex="-1">3 · Formular erstellen (3 Minuten) <a class="header-anchor" href="#_3-·-formular-erstellen-3-minuten" aria-label="Permalink to &quot;3 · Formular erstellen (3 Minuten)&quot;">​</a></h2><ol><li>Wählen Sie in der Seitenleiste unter dem Grid <strong>Formular erstellen</strong> und nennen Sie es <code>Anmeldung</code>.</li><li>Fügen Sie über <strong>Felder Hinzufügen</strong> die Felder <code>Name</code>, <code>E-Mail</code> und <code>Personen</code> hinzu — <strong>nicht</strong> <code>Status</code>.</li><li>Setzen Sie <code>Name</code> und <code>E-Mail</code> auf <strong>Pflichtfeld</strong>.</li><li>Tragen Sie im Reiter <strong>Layout</strong> einen Titel ein, etwa <code>Anmeldung zum Sommerfest</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Status gehört nicht ins Formular</p><p>Der Status ist eine interne Angabe, die Sie vergeben — nicht die anmeldende Person. Alles, was das Formular nicht abfragt, bleibt beim Absenden leer.</p></div><p>→ <a href="/formulare/formular-erstellen">Formular erstellen</a></p><h2 id="_4-·-formular-teilen-1-minute" tabindex="-1">4 · Formular teilen (1 Minute) <a class="header-anchor" href="#_4-·-formular-teilen-1-minute" aria-label="Permalink to &quot;4 · Formular teilen (1 Minute)&quot;">​</a></h2><ol><li>Klicken Sie auf <strong>Link erstellen</strong>.</li><li>Kopieren Sie den Link — oder nutzen Sie den QR-Code.</li><li>Testen Sie das Formular selbst über <strong>Vorschau in neuem Tab</strong>.</li></ol><div class="danger custom-block"><p class="custom-block-title">Der Link ist standardmäßig öffentlich</p><p>Jede Person mit dem Link kann das Formular ausfüllen. Für ein Sommerfest ist das gewollt. Bei internen oder sensiblen Formularen setzen Sie vorher <strong>Beschränkungen festlegen</strong>.</p><p>→ <a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></p></div><p>Senden Sie das Formular einmal mit Ihrer eigenen Adresse ab. Der Eintrag erscheint sofort im Grid.</p><h2 id="_5-·-bestatigung-automatisieren-4-minuten" tabindex="-1">5 · Bestätigung automatisieren (4 Minuten) <a class="header-anchor" href="#_5-·-bestatigung-automatisieren-4-minuten" aria-label="Permalink to &quot;5 · Bestätigung automatisieren (4 Minuten)&quot;">​</a></h2><ol><li>Öffnen Sie in der Seitenleiste <strong>Flows</strong> und klicken Sie <strong>Flow erstellen</strong>. Nennen Sie ihn <code>Bestätigung senden</code>.</li><li>Wählen Sie im Reiter <strong>Auslöser</strong> den Eintrag <strong>Eintrag per Formular</strong> und darin Grid und Formular.</li><li>Wählen Sie im Reiter <strong>Aktionen</strong> den Eintrag <strong>E-Mail</strong> und verbinden Sie ihn mit dem Auslöser.</li><li>Konfigurieren Sie die E-Mail: <ul><li><strong>An</strong>: über <em>Werte aus vorherigen Schritten verwenden</em> das Feld <code>E-Mail</code></li><li><strong>Betreff</strong>: <code>Ihre Anmeldung ist angekommen</code></li><li><strong>Inhalt</strong>: fester Text, ergänzt um das Feld <code>Name</code></li></ul></li></ol><div class="danger custom-block"><p class="custom-block-title">Vor dem Scharfschalten testen</p><p>Nutzen Sie <strong>Flow testen</strong> — der Schritt verwendet die letzte Zeile des Grids, also Ihren eigenen Testeintrag.</p><p>Ein Testlauf ist <strong>kein Trockenlauf</strong>: Die E-Mail geht wirklich raus. Deshalb ist die eigene Adresse als Testdatensatz wichtig.</p></div><p>Prüfen Sie im Reiter <strong>Verlauf</strong>, ob die Ausführung den Status <em>Fertig</em> hat.</p><p>→ <a href="/flows/ersten-flow-bauen">Ersten Flow bauen</a></p><h2 id="_6-·-uberblick-schaffen-2-minuten" tabindex="-1">6 · Überblick schaffen (2 Minuten) <a class="header-anchor" href="#_6-·-uberblick-schaffen-2-minuten" aria-label="Permalink to &quot;6 · Überblick schaffen (2 Minuten)&quot;">​</a></h2><p>Legen Sie zwei zusätzliche <a href="/ansichten/was-ist-eine-ansicht">Ansichten</a> auf dasselbe Grid:</p><p><strong>Kanban nach Status</strong> — zeigt Anmeldungen als Karten in den Spalten <code>Neu</code>, <code>Bestätigt</code>, <code>Abgesagt</code>. Karten lassen sich per Drag &amp; Drop verschieben.</p><p><strong>Tabelle „Offen&quot;</strong> — eine Grid-Ansicht mit dem Filter <code>Status</code> <code>entspricht</code> <code>Neu</code>.</p><div class="tip custom-block"><p class="custom-block-title">Alle Ansichten zeigen dieselben Daten</p><p>Sie legen keine Kopien an. Ändern Sie einen Eintrag im Kanban-Board, ist die Änderung sofort überall sichtbar.</p></div><p>Blenden Sie in der Tabelle über die Summenzeile die <strong>Summe</strong> der Spalte <code>Personen</code> ein — schon wissen Sie, wie viele Menschen kommen.</p><hr><h2 id="was-sie-jetzt-haben" tabindex="-1">Was Sie jetzt haben <a class="header-anchor" href="#was-sie-jetzt-haben" aria-label="Permalink to &quot;Was Sie jetzt haben&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Space „Veranstaltungen&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid „Anmeldungen&quot;</span></span>
<span class="line"><span>│   ├── Ansicht „Alle Anmeldungen&quot;    (Tabelle)</span></span>
<span class="line"><span>│   ├── Ansicht „Offen&quot;               (Tabelle, gefiltert)</span></span>
<span class="line"><span>│   ├── Ansicht „Nach Status&quot;         (Kanban)</span></span>
<span class="line"><span>│   └── Formular „Anmeldung&quot;          → öffentlich geteilt</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Flow „Bestätigung senden&quot;</span></span>
<span class="line"><span>    ├── Auslöser: Eintrag per Formular</span></span>
<span class="line"><span>    └── Aktion:   E-Mail</span></span></code></pre></div><p>Eine funktionierende Anwendung: Erfassung, Automatisierung und Übersicht.</p><h2 id="naheliegende-nachste-schritte" tabindex="-1">Naheliegende nächste Schritte <a class="header-anchor" href="#naheliegende-nachste-schritte" aria-label="Permalink to &quot;Naheliegende nächste Schritte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Weg</th></tr></thead><tbody><tr><td>Anmeldungen einer Person zuordnen</td><td>Zweites Grid <code>Veranstaltungen</code>, <a href="/grids/verknuepfungen">verknüpfen</a></td></tr><tr><td>Teilnehmerliste veröffentlichen</td><td><a href="/seiten/auswertungen">Seite mit eingebetteter Ansicht</a></td></tr><tr><td>Kollegen mitarbeiten lassen</td><td><a href="/zusammenarbeit/personen-einladen">Personen einladen</a></td></tr><tr><td>Absagen automatisch behandeln</td><td>Flow mit Auslöser <em>Eintrag wurde geändert</em></td></tr><tr><td>Bestätigung erst nach Prüfung</td><td><a href="/flows/seiten-in-flows">Seiten in Flows</a></td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/erste-schritte/was-ist-apptivegrid">Was ist ApptiveGrid</a> — die Begriffe im Zusammenhang</li><li><a href="/erste-schritte/oberflaeche">Die Oberfläche im Überblick</a></li><li><a href="/erste-schritte/vorlagen">Mit einer Vorlage starten</a></li></ul>`,43)])])}const f=n(d,[["render",o]]);export{b as __pageData,f as default};
